        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    hex_map = {'A': 11, 'B': 13, 'C': 17, 'D': 19, 'E': 23, 'F': 29}
    count = 0
    for digit in num:
        if digit in hex_map:
            if is_prime(hex_map[digit]):
                count += 1
        elif is_prime(int(digit, 16)):
            count += 1
    return count
